#include "Web.h"
namespace web {
const char page[]=R"WEB(<!doctype html><html lang="vi"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="color-scheme" content="light dark"><title>Robot Cua</title>
<style>body{font:17px system-ui,sans-serif;max-width:520px;margin:auto;padding:16px}button,input,select{font:inherit;padding:12px;border-radius:12px;min-height:48px;max-width:100%}button{cursor:pointer}button:disabled{opacity:.5}#pad{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}#pad button{touch-action:none;user-select:none;-webkit-user-select:none}#pad .held{background:#116b97;color:white}label{display:block;margin:14px 0}input,select{box-sizing:border-box;width:100%}.row{display:flex;gap:8px;align-items:center;justify-content:space-between;margin:10px 0}section{margin-bottom:20px}#notice{min-height:3em}a{display:inline-block;padding:12px}small{display:block;margin-top:20px}#center,#save{width:100%;margin:8px 0}</style>
<h1>Robot Cua</h1><p id="notice" role="status" aria-live="polite">Đang kết nối…</p>
<section id="setup" hidden><h2>Nối Wi-Fi nhà</h2><p>Chọn Wi-Fi 2,4 GHz. Không cần internet.</p><button id="scan" type="button">Tìm Wi-Fi</button><form id="wifi"><label>Wi-Fi<select id="ssid" required></select></label><label>Mật khẩu<input id="password" type="password" maxlength="63" autocomplete="off"></label><button id="join">Kết nối</button></form><p>Sau khi nối thành công: điện thoại trở về Wi-Fi nhà, quét QR mới trên màn hình cua. Nếu không tự mở, vào <b>http://192.168.4.1/</b>.</p></section>
<section id="drive" hidden><h2>Giữ để đi, thả để dừng</h2><div id="pad"><button data-dir="fl">↖<br>Xiên tới trái</button><button data-dir="forward">↑<br>Tới</button><button data-dir="fr">↗<br>Xiên tới phải</button><button data-dir="left">←<br>Trái</button><button id="stop">DỪNG</button><button data-dir="right">→<br>Phải</button><button data-dir="bl">↙<br>Xiên lui trái</button><button data-dir="back">↓<br>Lui</button><button data-dir="br">↘<br>Xiên lui phải</button></div><div class="row"><button id="light">Bật đèn</button><a href="/rap">Trang Ráp</a></div><p>Trái/phải là dáng đi ngang dự kiến. Chuyển động thật chưa được thử. Mất liên lạc: cua tự dừng.</p></section>
<section id="assembly" hidden><h2>Ráp và chỉnh tâm</h2><p>Kê thân để chân không chạm bàn. Tháo horn trước lần đưa về giữa. Đang Ráp thì các nút đi bị khóa, kể cả ở điện thoại khác.</p><button id="center">Đưa cả 8 servo về 90° để gắn horn</button><p>Gắn horn đúng dáng đứng. Tâm +/− chỉ sửa lệch răng horn, giới hạn ±15°.</p><div id="trims"></div><button id="save">Lưu tâm</button><button id="reset">Xóa chỉnh tâm (rồi bấm Lưu)</button><div class="row"><button id="exit">Xong Ráp — về điều khiển</button></div><p>Quy ước: FL trước trái, FR trước phải, RL sau trái, RR sau phải; nhìn từ trên với đầu cua hướng ra xa. Dấu + tăng xung PWM. GIẢ ĐỊNH trục quay ngược chiều kim đồng hồ khi nhìn phía horn; thử từng nấc nhỏ khi kê chân.</p></section><small>Firmware nguồn mở GPLv3+; không bảo hành. Nguồn và giấy phép đi kèm bộ file.</small>
<script>
'use strict';
const $=id=>document.getElementById(id), rap=location.pathname==='/rap';
const client=Array.from(crypto.getRandomValues(new Uint32Array(3)),x=>x.toString(16)).join('');
let seq=0, held=null, timer=null, sending=false, state=null, alive=true;
function note(s){$('notice').textContent=s;}
async function post(path,args={}){const r=await fetch(path,{method:'POST',body:new URLSearchParams(args),cache:'no-store',signal:AbortSignal.timeout(450)});const j=await r.json();if(!r.ok)throw Error(j.message);return j;}
function stop(){held=null;clearInterval(timer);timer=null;document.querySelectorAll('.held').forEach(b=>b.classList.remove('held'));const body=new URLSearchParams({client,seq:String(++seq)});if(navigator.sendBeacon)navigator.sendBeacon('/api/stop',body);else fetch('/api/stop',{method:'POST',body,keepalive:true}).catch(()=>{});}
async function beat(){if(!held||sending)return;const dir=held, n=++seq;sending=true;try{await post('/api/move',{client,seq:String(n),dir});}catch(e){stop();note('Đã dừng: '+e.message);}finally{sending=false;}}
function press(button,e){if(e.button!==undefined&&e.button!==0)return;e.preventDefault();if(!state||!state.ready||state.assembly||!state.online||held)return;held=button.dataset.dir;button.classList.add('held');if(e.pointerId!==undefined)button.setPointerCapture(e.pointerId);beat();timer=setInterval(beat,200);}
document.querySelectorAll('[data-dir]').forEach(b=>{b.addEventListener('pointerdown',e=>press(b,e));b.addEventListener('pointerup',stop);b.addEventListener('pointercancel',stop);b.addEventListener('lostpointercapture',()=>{if(held===b.dataset.dir)stop();});b.addEventListener('contextmenu',e=>e.preventDefault());b.addEventListener('keydown',e=>{if((e.key===' '||e.key==='Enter')&&!e.repeat)press(b,e);});b.addEventListener('keyup',e=>{if(e.key===' '||e.key==='Enter')stop();});});
$('stop').onclick=stop;window.addEventListener('blur',stop);window.addEventListener('pagehide',()=>{alive=false;stop();});document.addEventListener('visibilitychange',()=>{if(document.hidden)stop();});window.addEventListener('offline',stop);
async function scan(){try{const r=await fetch('/api/scan',{cache:'no-store'});const j=await r.json();if(j.pending){setTimeout(scan,800);return;}$('ssid').replaceChildren();for(const s of j.ssids){const o=document.createElement('option');o.value=s;o.textContent=s;$('ssid').append(o);}if(!j.ssids.length)note('Chưa thấy Wi-Fi 2,4 GHz. Bấm Tìm Wi-Fi để thử lại.');}catch(e){note('Chưa tìm được Wi-Fi. Bấm Tìm Wi-Fi để thử lại.');}}
$('scan').onclick=scan;$('wifi').onsubmit=async e=>{e.preventDefault();stop();$('join').disabled=true;try{const j=await post('/api/wifi',{ssid:$('ssid').value,password:$('password').value});$('password').value='';note(j.message);}catch(e){note(e.message);}finally{$('join').disabled=false;}};
$('light').onclick=async()=>{try{await post('/api/light',{on:state&&state.light?'0':'1'});await status();}catch(e){note(e.message);}};
async function assembly(op){stop();try{const j=await post('/api/assembly',{op});note(j.message);await status();return true;}catch(e){note(e.message);return false;}}
$('center').onclick=()=>assembly('center');$('save').onclick=()=>assembly('save');$('reset').onclick=()=>assembly('reset');$('exit').onclick=async()=>{if(await assembly('exit'))location.href='/';};
const names=['FL hông · CH0','FL gối · CH1','FR hông · CH2','FR gối · CH3','RL hông · CH4','RL gối · CH5','RR hông · CH6','RR gối · CH7'];
for(let ch=0;ch<8;ch++){const row=document.createElement('div');row.className='row';const name=document.createElement('span');name.textContent=names[ch];row.append(name);for(const delta of [-1,1]){const b=document.createElement('button');b.textContent=delta===1?'+':'−';b.setAttribute('aria-label',names[ch]+(delta===1?' tăng 1 độ':' giảm 1 độ'));b.onclick=async()=>{try{await post('/api/trim',{ch,delta});await status();}catch(e){note(e.message);}};row.append(b);}const value=document.createElement('span');value.id='t'+ch;row.append(value);$('trims').append(row);}
async function status(){try{const r=await fetch('/api/status',{cache:'no-store',signal:AbortSignal.timeout(1000)});state=await r.json();note(state.fault?'Không thấy PCA9685. Tắt nguồn, kiểm lại dây.':state.wifi+(state.assembly?' · Đang Ráp':state.ready?'':' · Servo đang bật lần lượt'));$('setup').hidden=state.online;$('drive').hidden=rap||!state.online;$('assembly').hidden=!rap||!state.online;document.querySelectorAll('[data-dir]').forEach(b=>b.disabled=!state.ready||state.assembly||!state.online||state.fault);$('light').textContent=state.light?'Tắt đèn':'Bật đèn';for(let i=0;i<8;i++)$('t'+i).textContent=state.trim[i]+'°';if(held&&(!state.online||state.assembly||state.fault))stop();}catch(e){stop();note('Mất liên lạc. Cua tự dừng. Xem QR trên màn hình.');}}
(async()=>{await status();if(rap){await assembly('enter');}else if(!state||!state.online)scan();while(alive){await new Promise(r=>setTimeout(r,1000));await status();}})();
</script></html>)WEB";
}
